#!/bin/sh
# Example OpenWrt script: persistent static routes through the tunnel interface (uci).
# Generated by NetRoute: https://alexander2k.github.io/netroute-site/
#
# Run on the router: sh openwrt-routes.sh
# interface=wg0 is the logical name of your tunnel in /etc/config/network;
# change it (and add a gateway line) to match your setup.
# Replace the example networks with NetRoute output for your sites.

uci add network route
uci set network.@route[-1].interface='wg0'
uci set network.@route[-1].target='140.82.112.0/20'
uci add network route
uci set network.@route[-1].interface='wg0'
uci set network.@route[-1].target='185.199.108.0/22'
uci add network route6
uci set network.@route6[-1].interface='wg0'
uci set network.@route6[-1].target='2606:50c0::/32'
uci commit network
/etc/init.d/network reload
